+}
+
+export type ObservationSet={conditionKey:string;items:Record<string,Result>};
+export function recordObservation(previous:ObservationSet,result:Result):ObservationSet {
+  const guide=lessonGuide(result.parameters);
+  const value=result.parameters[guide.control];
+  if(!guide.steps.some(step=>step.value===value))return previous;
+  const items=previous.conditionKey===guide.conditionKey?previous.items:{};
+  return {conditionKey:guide.conditionKey,items:{...items,[String(value)]:result}};
+}
+
+export function lowestObserved(guide:LessonGuide,observations:ObservationSet):GuideStep|null {
+  if(guide.conditionKey!==observations.conditionKey)return null;
