    text = re.sub(r'(?i)(Bearer\s+)[A-Za-z0-9._-]{12,}', r'\1[REDACTED]', text)
    return text


def has_local_identifier(text: str) -> bool:
    return bool(re.search(r'''(?i)(?<![a-z0-9])[a-z]:(?:\\+|/+)(?=[^\\/"'\s:{}\[\]])''', text)) or Path.home().name in text
