      >
        <defs>
          <clipPath id={id}>
            <rect x={left} y={top} width={w} height={h} />
          </clipPath>
        </defs>
        {[0, 0.25, 0.5, 0.75, 1].map((t) => (
          <g key={t}>
            <line
              x1={left + t * w}
              x2={left + t * w}
              y1={top}
              y2={height - bottom}
              stroke="#ffffff88"
            />
            <line
              x1={left}
              x2={width - right}
              y1={top + t * h}
              y2={top + t * h}
              stroke="#ffffff88"
            />
            <text
              x={left + t * w}
              y={height - bottom + 20}
              textAnchor="middle"
              className="axis-text"
            >
              {(xmin + t * (xmax - xmin)).toFixed(1)}
            </text>
            <text
              x={left - 8}
              y={top + t * h + 4}
              textAnchor="end"
              className="axis-text"
            >
              {(ymax - t * (ymax - ymin)).toFixed(1)}
            </text>
          </g>
        ))}
        <g clipPath={`url(#${id})`}>
          {result.training.map((p, i) => point(p, true, i))}
          {result.validation.map((p, i) => point(p, false, i))}
        </g>
        <text
          x={width - right}
          y={height - 1}
          textAnchor="end"
          className="axis-label"
        >
          {result.dataset.features[0]}
        </text>
        <text x={left} y="12" className="axis-label">
          {result.dataset.features[1]}
        </text>
      </svg>
      {clipped && (
        <p className="concept-clip">
          部分样本超出视窗，准确率仍按完整划分计算。
        </p>
      )}
    </div>
  );
