+  const [snapshot,setSnapshot] = useState<ClassResult|null>(null),[curtain,setCurtain] = useState(.5),[feedback,setFeedback] = useState("");
+  useEffect(()=>{const saved=readPlayDraft(localStorage.getItem("fitlab-class-play-v1"));if(saved)setGame(saved);},[]);
+  useEffect(()=>{if(ready){setGame(g=>g.key===key?g:{...g,key,found:[],revealed:false});setFeedback("");}},[key,ready]);
+  useEffect(()=>{if(ready&&game.key===key)localStorage.setItem("fitlab-class-play-v1",JSON.stringify(game));},[game,key,ready]);
+  const matched=!!result&&!pending&&classKey(result.parameters)===key;
+  const found=matched&&game.key===key?verifiedFinds(result.validation,game.found):[];
+  const paired=game.mode==="compare"&&canCompareRegions(snapshot,result);
+  function mode(value:PlayMode){setFeedback("");setGame(g=>g.mode===value?g:{key,mode:value,found:[],revealed:false});}
+  function recipe(id:ClassRecipeId){const next=recipeInput(id,classDefaults),row=classRecipes.find(r=>r.id===id)!;setSnapshot(null);setCurtain(.5);setFeedback("");setGame({key:classKey(next),mode:row.mode,found:[],revealed:false});setInput(next);}
